"""Curated learning material for the Software Security Engineering lessons."""

GUIDES = {
    1: {"module": "Fundamentos", "title": "Segurança em todo o ciclo de vida", "question": "Em que momento a segurança começa?", "summary": "Segurança é uma preocupação de engenharia presente desde a conversa inicial até a operação do sistema.", "objectives": ("Distinguir ativos, ameaças, vulnerabilidades e ataques.", "Relacionar segurança aos requisitos não funcionais.", "Reconhecer as etapas de um ciclo de desenvolvimento seguro."), "concepts": (("Ativo e propriedades", "Ativo é tudo que tem valor para o negócio. Confidencialidade, integridade e disponibilidade orientam o que precisa ser protegido.", "Pergunte: qual dado, operação ou recurso causa dano se for exposto, alterado ou ficar indisponível?"), ("Ameaça, vulnerabilidade e ataque", "A ameaça é uma possibilidade de dano. A vulnerabilidade é a fraqueza explorável. O ataque é a exploração efetiva dessa fraqueza.", "Não trate os três termos como sinônimos ao documentar um risco."), ("Segurança contínua", "Requisitos, modelagem de ameaças, arquitetura, implementação, testes e operação precisam preservar as decisões de segurança.", "SAST analisa código; DAST testa o sistema em execução.")), "quiz": (("Uma vulnerabilidade já torna um sistema inseguro?", ("Não, são necessárias várias.", "Sim, ela pode ser explorada.", "Somente se houver ataque confirmado."), 1, "Uma única vulnerabilidade pode comprometer a confiança no sistema."), ("Qual sequência está correta?", ("Ataque → ameaça → vulnerabilidade", "Vulnerabilidade → ativo → requisito", "Ameaça → vulnerabilidade → ataque"), 2, "A ameaça existe como possibilidade; a vulnerabilidade permite a exploração; o ataque a concretiza."))},
    2: {"module": "Requisitos seguros", "title": "Requisitos de segurança desde a elicitação", "question": "Como transformar uma preocupação do cliente em algo verificável?", "summary": "A segurança deixa de ser uma frase genérica quando é descoberta nas entrevistas e escrita como comportamento esperado do sistema.", "objectives": ("Separar requisito funcional de requisito não funcional.", "Conduzir perguntas que revelem ativos e preocupações.", "Escrever requisitos de segurança observáveis."), "concepts": (("Funcional não basta", "Uma funcionalidade descreve o que o sistema faz. Um requisito não funcional define qual qualidade esse comportamento precisa manter, como segurança e disponibilidade.", ""), ("Entrevista orientada a risco", "Além de perguntar o fluxo normal, pergunte o que não pode acontecer, quais dados são sensíveis e quem pode executar cada ação.", "Use perguntas abertas antes de propor controles."), ("Requisito verificável", "'O sistema deve ser seguro' não orienta implementação. Prefira regras como 'somente usuários autorizados podem consultar determinado dado'.", "Todo requisito deve permitir uma verificação posterior.")), "quiz": (("'O sistema deve permitir agendar consultas' é um requisito:", ("Funcional.", "Não funcional.", "De auditoria."), 0, "Ele descreve uma capacidade oferecida pelo sistema."), ("Qual pergunta revela uma preocupação de segurança?", ("Qual cor deve ter o botão?", "Que informação não pode ser acessada indevidamente?", "Quantas telas terá o sistema?"), 1, "Ela direciona a conversa para ativos e ações proibidas."))},
    3: {"module": "Modelagem de ameaças", "title": "STRIDE: perguntas para descobrir ameaças", "question": "Que tipo de abuso pode comprometer cada parte do sistema?", "summary": "STRIDE não é uma lista de ataques prontos. É uma estrutura de perguntas para examinar ameaças de forma sistemática.", "objectives": ("Aplicar as seis categorias do STRIDE.", "Diferenciar caso de uso e caso de abuso.", "Conectar ameaça, ativo e impacto."), "concepts": (("S e T", "Spoofing é falsificação de identidade. Tampering é alteração indevida de dados, mensagens ou estado.", "Pergunte quem pode se passar por outra pessoa e o que pode ser alterado."), ("R e I", "Repudiation ocorre quando uma ação pode ser negada sem evidência confiável. Information Disclosure é a exposição indevida de informação.", "Auditoria e controle de acesso respondem a perguntas diferentes."), ("D e E", "Denial of Service reduz disponibilidade. Elevation of Privilege amplia permissões além do permitido.", "Pergunte como o sistema se comporta sob abuso e quem consegue executar ações privilegiadas.")), "quiz": (("Um usuário altera o valor de um pedido sem permissão. Qual categoria?", ("Tampering", "Repudiation", "Spoofing"), 0, "Tampering trata de alteração indevida."), ("Um caso de abuso descreve:", ("O fluxo esperado do usuário.", "Uma ação indesejada que o sistema deve impedir ou controlar.", "A tecnologia escolhida para o sistema."), 1, "Ele ajuda a tornar explícitos caminhos maliciosos ou indevidos."))},
    4: {"module": "Documentação", "title": "Documentando ameaças e casos de abuso", "question": "Como tornar a análise de segurança revisável pelo grupo?", "summary": "A documentação registra o raciocínio da modelagem de ameaças e mantém a evolução do trabalho rastreável no GitHub.", "objectives": ("Estruturar uma documentação de ameaças.", "Registrar casos de abuso com contexto.", "Usar commits para evidenciar evolução."), "concepts": (("Estrutura legível", "Organize o documento com contexto do sistema, ativos, ameaças STRIDE, interpretação e casos de abuso.", "Uma pessoa do grupo deve conseguir localizar o motivo de cada ameaça."), ("Caso de abuso completo", "Registre ator, objetivo, condições, sequência de ações, impacto e relação com STRIDE.", "Evite nomes vagos como 'ataque ao sistema'."), ("Histórico como evidência", "Commits pequenos e descritivos tornam visíveis autoria, revisão e amadurecimento da análise.", "Registre a intenção da mudança, não apenas 'ajustes'.")), "quiz": (("Qual item torna um caso de abuso verificável?", ("A cor do diagrama.", "A sequência de ações e o impacto esperado.", "A ferramenta de edição usada."), 1, "A sequência mostra como o abuso ocorre e o impacto explica sua relevância."), ("Por que usar commits descritivos?", ("Para aumentar o tamanho do repositório.", "Para evidenciar evolução e participação no trabalho.", "Para substituir a documentação."), 1, "O histórico complementa, mas não substitui, o documento."))},
    5: {"module": "Elicitação", "title": "Entrevistas que revelam ameaças", "question": "Como descobrir o que o cliente quer impedir, e não apenas o que quer construir?", "summary": "A entrevista parte do domínio e das funcionalidades, mas inclui perguntas que expõem ações indevidas, dados sensíveis e consequências.", "objectives": ("Guiar uma entrevista orientada ao domínio.", "Identificar ativos e atores relevantes.", "Converter respostas em ameaças e casos de abuso."), "concepts": (("Comece pelo trabalho real", "Entenda quem usa o sistema, quais decisões toma e quais informações movimenta antes de falar de controles.", ""), ("Perguntas de negação", "Perguntas como 'o que não pode ser alterado indevidamente?' revelam requisitos de proteção e caminhos de abuso.", ""), ("Do relato ao artefato", "Respostas sobre credenciais, dados e operações críticas alimentam ativos, ameaças, casos de abuso e requisitos.", "Não invente preocupações que a entrevista não sustentou.")), "quiz": (("Qual pergunta é mais útil para revelar um ativo?", ("Qual navegador o cliente usa?", "Quais informações precisam ser protegidas?", "Qual fonte o cliente prefere?"), 1, "Ela aponta dados e recursos valiosos para o negócio."), ("A palavra 'indevidamente' em uma pergunta ajuda a:", ("Descrever somente o fluxo feliz.", "Explorar ações que o sistema precisa impedir.", "Escolher uma linguagem de programação."), 1, "Ela desloca a conversa para casos de abuso."))},
    6: {"module": "Risco", "title": "Da ameaça ao risco: priorização", "question": "O que precisa ser tratado primeiro?", "summary": "Risco combina a possibilidade de uma ameaça se concretizar com as consequências para ativos, usuários e operação.", "objectives": ("Diferenciar ameaça de risco.", "Avaliar probabilidade e impacto.", "Justificar uma ordem de prioridade."), "concepts": (("Ameaça não é prioridade", "Ameaças diferentes não têm o mesmo peso. O risco ajuda a decidir onde investir primeiro.", ""), ("Probabilidade e impacto", "Probabilidade estima a chance de ocorrência. Impacto estima a consequência se ela ocorrer.", "As duas avaliações precisam de justificativa contextual."), ("Registro de risco", "Um registro reúne identificador, evento, ativos afetados, avaliações, nível, justificativa e tratamento planejado.", "O número orienta; a justificativa sustenta a decisão.")), "quiz": (("Um evento raro, mas devastador, pode ser prioridade?", ("Não, porque é raro.", "Sim, porque o impacto também compõe o risco.", "Somente se não houver ativos."), 1, "Probabilidade baixa não elimina um impacto crítico."), ("Qual informação torna a classificação de risco auditável?", ("A justificativa de probabilidade e impacto.", "A preferência pessoal da equipe.", "A cor da tabela."), 0, "A justificativa permite revisar a decisão posteriormente."))},
    7: {"module": "Tratamento de riscos", "title": "Do risco ao controle com NIST CSF 2.0", "question": "Como transformar prioridade em uma ação de segurança concreta?", "summary": "Depois de priorizar riscos, a equipe decide como tratá-los, atribui responsabilidades e relaciona controles às funções do NIST CSF.", "objectives": ("Distinguir estratégias de tratamento de risco.", "Usar as seis funções do NIST CSF 2.0.", "Relacionar controle, responsável e evidência."), "concepts": (("Tratar é decidir", "Um risco pode ser mitigado, evitado, transferido ou aceito com condições explícitas.", "Aceitar não é ignorar: exige responsável e revisão."), ("Govern e Identify", "Govern define responsabilidade, política e apetite a risco. Identify conhece ativos, contexto, dependências e riscos.", ""), ("Protect, Detect, Respond e Recover", "Proteger reduz exposição; detectar encontra sinais; responder contém e comunica; recuperar restaura a operação e aprende com o incidente.", "As funções se complementam, não são uma lista de tecnologias.")), "quiz": (("Qual função define quem pode aceitar determinado risco?", ("Govern", "Detect", "Recover"), 0, "Governança define responsabilidades e critérios de decisão."), ("Autenticação multifator é exemplo principalmente de:", ("Protect", "Recover", "Identify"), 0, "Ela reduz a chance de acesso indevido."))},
    8: {"module": "Arquitetura", "title": "Projetando uma arquitetura segura", "question": "Que decisões estruturais reduzem risco antes do código existir?", "summary": "Arquitetura segura acrescenta perguntas de confiança, exposição, responsabilidade e falha às decisões tradicionais de componentes e integrações.", "objectives": ("Identificar decisões arquiteturais de segurança.", "Avaliar confiança entre componentes.", "Planejar falhas e dependências."), "concepts": (("Responsabilidades visíveis", "A arquitetura deve deixar claro quem autentica, autoriza, valida, armazena e audita.", "Uma caixa no diagrama só vale se a responsabilidade for implementada depois."), ("Limites de confiança", "Componentes externos e entradas atravessam limites onde informações precisam ser verificadas antes de influenciar decisões.", ""), ("Falha planejada", "Redundância, isolamento e tratamento de indisponibilidade evitam que uma falha simples derrube uma operação crítica.", "Planeje o comportamento degradado, não apenas o cenário ideal.")), "quiz": (("Uma decisão arquitetural segura responde principalmente a:", ("Uma ameaça ou risco relevante.", "Uma preferência estética.", "Um nome de tecnologia."), 0, "O controle precisa ter um motivo de segurança rastreável."), ("Por que avaliar componentes externos?", ("Porque toda integração é confiável por padrão.", "Porque eles podem ampliar a superfície de ataque e introduzir dependências.", "Somente para reduzir custos."), 1, "Integrações também atravessam limites de confiança."))},
    9: {"module": "Arquitetura aplicada", "title": "Estudo de caso: sistema de matrículas", "question": "Como distribuir decisões críticas sem perder controle?", "summary": "O estudo de caso separa papéis, serviços, dados e decisões para que a arquitetura deixe explícito quem pode fazer cada operação.", "objectives": ("Mapear atores, componentes e dados.", "Separar responsabilidades críticas.", "Distinguir modularização de microsserviços."), "concepts": (("Mapa do sistema", "Estudantes, secretaria, coordenação, autenticação, oferta de turmas, matrícula, notificações e auditoria possuem papéis diferentes.", ""), ("Separação de responsabilidades", "A arquitetura segura explicita qual componente decide, quais dados consulta e de quem confia.", ""), ("Não é sobre microsserviços", "Separar responsabilidades não obriga criar muitos serviços. Uma aplicação modular também pode preservar limites claros.", "Escolha a forma de implantação depois de definir as responsabilidades.")), "quiz": (("O principal objetivo de separar responsabilidades é:", ("Criar o máximo de serviços possível.", "Tornar visíveis decisões, dados e relações de confiança.", "Eliminar toda comunicação entre componentes."), 1, "A clareza das responsabilidades vem antes da tecnologia."), ("Auditoria deve registrar:", ("Quem fez o quê e o resultado relevante.", "Somente erros de compilação.", "A cor da interface."), 0, "Registros apoiam rastreabilidade e investigação."))},
    10: {"module": "Limites de confiança", "title": "Não confie no cliente", "question": "Quais decisões precisam continuar no servidor?", "summary": "Tudo que chega do navegador ou de outro cliente pode ser manipulado. O servidor deve validar e manter autoridade sobre decisões críticas.", "objectives": ("Reconhecer entradas não confiáveis.", "Definir limites de confiança.", "Preservar validação e autorização no servidor."), "concepts": (("Cliente não é fronteira", "Campos ocultos, botões desabilitados e regras de interface não impedem requisições forjadas.", "A interface melhora a experiência; não substitui um controle de segurança."), ("Validação no servidor", "Dados externos precisam ser validados antes de alterar estado, consultar recursos ou conceder uma ação.", ""), ("Identidade e autoridade", "A identidade deve vir da sessão ou token validado. O cliente não deve decidir seu próprio papel nem permissões.", "")), "quiz": (("Ocultar um botão impede uma ação maliciosa?", ("Sim, sempre.", "Não; a requisição ainda pode ser criada fora da interface.", "Somente em dispositivos móveis."), 1, "O servidor é quem precisa negar operações não autorizadas."), ("De onde deve vir a identidade para uma operação crítica?", ("De um campo enviado pelo navegador.", "Do contexto autenticado no servidor.", "De um valor no HTML."), 1, "A origem precisa ser validada pela infraestrutura de autenticação."))},
    11: {"module": "Exposição", "title": "Ativos e superfície de ataque", "question": "O que merece proteção e por onde pode ser atacado?", "summary": "Antes de escolher controles, identifique o que tem valor e todos os pontos pelos quais um atacante pode influenciar o sistema.", "objectives": ("Inventariar ativos relevantes.", "Mapear superfícies de ataque.", "Reduzir exposição desnecessária."), "concepts": (("Ativos primeiro", "Credenciais, dados pessoais, regras de negócio, registros e disponibilidade só podem ser protegidos adequadamente se forem identificados.", ""), ("Superfície de ataque", "Endpoints, formulários, importações, integrações, contas administrativas e APIs legadas são pontos de entrada ou exposição.", ""), ("Menos exposição", "Cada recurso adicional exige proteção, manutenção e monitoramento. Remover o que não é necessário reduz risco.", "")), "quiz": (("Uma API legada sem uso é principalmente:", ("Uma superfície de ataque desnecessária.", "Uma garantia de disponibilidade.", "Um ativo que precisa ser público."), 0, "Eliminar recursos sem finalidade reduz possibilidades de exploração."), ("Por que listar ativos antes de controles?", ("Para saber o que tem valor e qual dano evitar.", "Para escolher cores de diagrama.", "Para dispensar modelagem de ameaças."), 0, "O valor do ativo orienta proteção e prioridade."))},
    12: {"module": "Princípios arquiteturais", "title": "Defesa em profundidade e consistência", "question": "Como evitar que uma única falha comprometa uma decisão crítica?", "summary": "Arquitetura segura combina minimização, privilégio mínimo, controles em camadas, auditoria e operações consistentes.", "objectives": ("Aplicar minimização de dados.", "Usar privilégio mínimo e auditoria.", "Reconhecer concorrência como um problema de segurança."), "concepts": (("Minimização", "Colete e exponha somente dados necessários para a finalidade. Menos dados disponíveis significa menor impacto de exposição.", ""), ("Privilégio mínimo e camadas", "Cada papel e componente recebe apenas as permissões necessárias. Controles independentes reduzem o efeito de uma falha isolada.", ""), ("Concorrência", "Duas solicitações simultâneas podem violar uma regra, como ocupar a última vaga duas vezes. A decisão precisa ser atômica e consistente.", "")), "quiz": (("Um professor precisa consultar todos os dados financeiros de todos os alunos?", ("Sim, para simplificar o sistema.", "Não, deve acessar apenas o necessário à finalidade.", "Somente fora do horário comercial."), 1, "Isso aplica minimização e privilégio mínimo."), ("Qual risco existe na última vaga com duas solicitações simultâneas?", ("Duplicidade por falta de operação consistente.", "Somente erro visual.", "Nenhum, pois há uma vaga."), 0, "A verificação e a confirmação precisam preservar a regra."))},
    13: {"module": "Decisões robustas", "title": "Sete decisões para uma arquitetura resistente", "question": "Que decisões evitam inconsistência, vazamento e propagação de falhas?", "summary": "A aula reúne decisões arquiteturais que preservam regras, isolam componentes, protegem segredos e dados, e separam ambientes.", "objectives": ("Aplicar idempotência e regras centralizadas.", "Proteger segredos e dados em todo o ciclo.", "Separar ambientes e conter impacto."), "concepts": (("Idempotência", "A mesma solicitação lógica deve produzir um único efeito, mesmo após repetição por clique ou falha de rede.", "Use identificador único, restrições e verificação de estado."), ("Regras centralizadas", "Uma regra crítica espalhada entre interface, API e rotinas paralelas pode divergir. Centralize a decisão no componente responsável.", ""), ("Segregação e segredos", "Um componente comprometido não deve abrir acesso ao restante. Senhas, chaves e tokens não pertencem ao código, logs ou repositórios.", ""), ("Dados e ambientes", "Proteja dados em trânsito, em repouso, backups, caches e testes. Homologação não deve expor a produção.", "Use dados sintéticos quando possível.")), "quiz": (("Reenviar a mesma solicitação não pode criar dois registros. Qual propriedade?", ("Idempotência", "Repúdio", "Escalabilidade"), 0, "Idempotência preserva um único efeito para a mesma ação lógica."), ("Onde uma chave de integração não deve ficar?", ("Em um gerenciador de segredos.", "Em logs e repositórios.", "Em acesso controlado."), 1, "Segredos expostos em código ou logs podem ser reutilizados por atacantes."))},
    14: {"module": "Disponibilidade", "title": "Arquitetura para picos de acesso", "question": "Como manter o serviço útil quando a demanda aumenta?", "summary": "Disponibilidade é uma propriedade de segurança. O sistema precisa absorver, limitar e observar carga sem perder decisões críticas.", "objectives": ("Reconhecer risco de indisponibilidade.", "Aplicar filas, cache e limitação de requisições.", "Planejar degradação e observabilidade."), "concepts": (("Picos são previsíveis", "Períodos de matrícula concentram acessos justamente quando a operação é mais importante.", "Capacidade deve ser planejada para o momento crítico, não para a média."), ("Controle de carga", "Filas, processamento assíncrono, cache de consultas e limitação de requisições reduzem sobrecarga e preservam recursos.", ""), ("Degradação controlada", "Operações menos críticas podem ser reduzidas para manter decisões essenciais disponíveis e consistentes.", ""), ("Observabilidade", "Logs protegidos, métricas e monitoramento permitem detectar pressão, investigar incidentes e melhorar a resposta.", "")), "quiz": (("Qual operação tende a ser boa candidata a cache?", ("Consulta de oferta que muda pouco.", "Confirmação crítica da última vaga.", "Alteração de senha."), 0, "Cache ajuda principalmente leituras repetidas e menos sensíveis à atualização imediata."), ("Por que limitar requisições?", ("Para impedir qualquer uso do sistema.", "Para conter abuso e evitar esgotamento de recursos.", "Para remover necessidade de monitoramento."), 1, "A limitação reduz pressão e ajuda a manter disponibilidade."))},
    15: {"module": "Rastreabilidade arquitetural", "title": "De STRIDE a decisões de arquitetura", "question": "Qual controle responde a cada tipo de ameaça?", "summary": "A arquitetura ganha sentido quando cada decisão está ligada a uma ameaça concreta, e não a uma lista genérica de boas práticas.", "objectives": ("Mapear STRIDE para decisões arquiteturais.", "Escolher controles coerentes com a ameaça.", "Explicar por que cada controle existe."), "concepts": (("Identidade e alteração", "Spoofing pede autenticação confiável. Tampering pede validação no servidor, regras centralizadas, integridade e transações.", ""), ("Evidência e privacidade", "Repudiation pede auditoria preservada. Information Disclosure pede autorização por recurso, minimização e segregação.", ""), ("Disponibilidade e privilégios", "Denial of Service pede isolamento, limites e monitoramento. Elevation of Privilege pede autorização específica e privilégio mínimo.", "")), "quiz": (("Logs protegidos ajudam principalmente a tratar:", ("Repudiation", "Tampering apenas", "Disponibilidade apenas"), 0, "Eles preservam evidência sobre quem realizou uma ação."), ("Autorização específica por recurso reduz sobretudo:", ("Information Disclosure e Elevation of Privilege.", "Somente disponibilidade.", "Somente cache desatualizado."), 0, "Ela evita acesso a dados ou operações além do permitido."))},
    16: {"module": "Implementação segura", "title": "Por que arquitetura segura não basta", "question": "Como impedir que o código anule uma boa decisão arquitetural?", "summary": "Diagramas organizam controles, mas somente a implementação consistente preserva autorização, validação, atomicidade e evidências.", "objectives": ("Transformar decisão arquitetural em regra de código.", "Reconhecer formas de enfraquecer controles.", "Verificar propriedades de segurança na implementação."), "concepts": (("Arquitetura é base", "Uma arquitetura segura torna a implementação viável, mas não cria código correto automaticamente.", ""), ("Preservar, não anular", "Se o código confia em um perfil enviado pelo cliente, ele anula uma autorização desenhada na arquitetura.", ""), ("Atomicidade", "Uma regra como 'há vaga disponível' precisa ser preservada na confirmação da operação, não apenas em uma consulta anterior.", "")), "quiz": (("Um campo 'perfil=secretaria' vindo do navegador é suficiente para autorizar uma ação?", ("Sim, se o botão estava oculto.", "Não, o servidor deve verificar a autorização confiável.", "Sim, se vier em JSON."), 1, "Dados do cliente não provam identidade nem permissão."), ("Uma boa arquitetura garante software seguro?", ("Sim, sempre.", "Não; a implementação pode enfraquecer seus controles.", "Somente em microsserviços."), 1, "Cada decisão precisa ser implementada e verificada."))},
    17: {"module": "Evidência", "title": "Da ameaça ao teste de segurança", "question": "Como demonstrar que um controle realmente funciona?", "summary": "Segurança precisa de uma cadeia rastreável entre ameaça, requisito, arquitetura, código, teste e evidência observável.", "objectives": ("Construir rastreabilidade de segurança.", "Definir critérios de aceitação negativos.", "Evitar atribuição em massa e confiança no cliente."), "concepts": (("Cadeia de rastreabilidade", "Uma ameaça motiva um requisito; o requisito motiva uma decisão arquitetural; o código implementa a decisão; o teste produz evidência.", ""), ("Critério de aceitação", "Além do fluxo feliz, defina o que o sistema deve negar, registrar e manter consistente diante de ações indevidas.", ""), ("Autoridade sobre campos", "O cliente informa somente o necessário. Identidade, permissões, prioridade e estado devem vir de contexto confiável ou ser calculados pelo servidor.", "Isso evita atribuição em massa de campos internos.")), "quiz": (("Qual sequência produz evidência de segurança?", ("Ameaça → requisito → arquitetura → código → teste", "Teste → ameaça → interface", "Código → cor → requisito"), 0, "A cadeia conecta a motivação do controle à sua verificação."), ("Por que não copiar todo JSON recebido para a entidade do banco?", ("Porque pode permitir alterar campos internos indevidamente.", "Porque JSON é sempre inválido.", "Porque elimina a necessidade de testes."), 0, "A atribuição em massa entrega ao cliente autoridade que pertence ao servidor."))},
}
